+body {
+  width: 340px;
+  font-family: -apple-system, Segoe UI, Roboto, sans-serif;
+  margin: 0;
+}
+
+#app {
+  display: flex;
+  flex-direction: column;
+  height: 420px;
+}
+
+#header {
+  padding: 10px;
+  border-bottom: 1px solid #e2e2e2;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+}
+
+#page-title {
+  font-size: 12px;
+  color: #555;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+
+#load-btn, #send-btn {
+  background: #2563eb;
+  color: white;
+  border: none;
+  border-radius: 6px;
+  padding: 6px 10px;
+  font-size: 13px;
+  cursor: pointer;
+}
+
+#load-btn:disabled, #send-btn:disabled {
+  background: #a5b4fc;
+  cursor: not-allowed;
+}
+
+#chat {
+  flex: 1;
+  overflow-y: auto;
+  padding: 10px;
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+}
+
+.msg {
+  padding: 8px 10px;
+  border-radius: 8px;
+  font-size: 13px;
+  max-width: 85%;
+  line-height: 1.4;
+}
+
+.msg.user {
+  align-self: flex-end;
+  background: #2563eb;
+  color: white;
+}
+
+.msg.bot {
+  align-self: flex-start;
+  background: #f1f1f1;
+  color: #111;
+}
+
+#input-row {
+  display: flex;
+  gap: 6px;
+  padding: 8px;
+  border-top: 1px solid #e2e2e2;
+}
+
+#question {
+  flex: 1;
+  padding: 6px 8px;
+  border: 1px solid #ccc;
+  border-radius: 6px;
+  font-size: 13px;
+}
+
+#status {
+  font-size: 11px;
+  color: #888;
+  padding: 0 10px 6px;
+  min-height: 14px;
+}
